/// error (E3), GC'd ids fall back to the on-disk log while it exists (AC4)
/// or degrade to the clean error once it is gone (E2), and everything else
/// gets the plain closest-ids result (AC2).
Future<ToolExecutionResult> _unknownOutputResult(
  ShellJobRegistry jobs,
  String id,
  List<String> closestIds,
  int maxLines,
) async {
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  final gcPath = jobs.prunedLogPath(id);
  if (gcPath != null) {
    final tail = await jobs.tailFromLog(gcPath, maxLines: maxLines);
    if (tail == null) throw StateError('unknown background job: $id');
    return ToolExecutionResult.text(
      'Job $id already exited; its log was compacted out of the registry. '
      'Tail from disk:\n'
      '${tail.isEmpty ? '(no output)' : tail}',
    );
  }
  return ToolExecutionResult.text(_unknownIdText(jobs, id, closestIds));
}

/// Issue #2201: the pre-stop honest wording for a job that is already
/// done — an adopted job has no exit code to report (liveness-only), a
/// registry-native job reports its real one. Null when [entry] still
/// runs (the caller proceeds to stop it).
ToolExecutionResult? _alreadyFinishedStopResult(
  ShellJobEntry entry,
  String id,
) {
  if (entry.isRunning) return null;
  return ToolExecutionResult.text(
    entry.isAdopted
        ? '$id already exited (adopted — liveness-only, no exit code)'
        : '$id already finished (exit code ${entry.exitCode})',
  );
}

/// Issue #2201 r3: `ShellJobEntry.stop` re-verifies the #478 start tag
/// before signaling. When the guard refused — the process was already
/// gone, or its pid was recycled onto a stranger — nothing was signaled,
/// so "Stopped" would be a lie. Null when the stop ran normally.
ToolExecutionResult? _refusedAdoptedStopResult(ShellJobEntry entry, String id) {
  if (entry.isRunning || !entry.isAdopted || entry.stopReason != null) {
    return null;
  }
  return ToolExecutionResult.text(
    '$id already exited (adopted — liveness-only, no exit code)',
  );
}

Future<ToolExecutionResult> _bashJobStopResult(
  ShellJobRegistry jobs,
  String? id,
) async {
  if (id == null) throw StateError('bash_job stop requires an id');
  final entry = jobs.job(id);
  if (entry != null) {
    final already = _alreadyFinishedStopResult(entry, id);
    if (already != null) return already;
    await entry.stop();
    final refused = _refusedAdoptedStopResult(entry, id);
    if (refused != null) return refused;
    // Issue #2260: bare "Stopped" only when the whole process group
    // verified gone. An adopted stop on a host without group leadership
    // (or with a failed verification scan) killed only the leader; a
    // partial kill names the surviving members. Both keep the manifest
    // record, and the next boot's sweep reaps the group through it.
    final survivors = entry.stopSurvivors;
    if (survivors != null && survivors.isNotEmpty) {
      final pids = [for (final s in survivors) 'pid ${s.pid}'].join(', ');
      return ToolExecutionResult.text(
        'Stopped the leader $id — ${survivors.length} process group '
        'member(s) still running: $pids. The job record is kept; the '
        'next boot reaps the survivors.',
      );
    }
    if (survivors == null) {
      return ToolExecutionResult.text(
        'Stopped the leader $id (pid ${entry.pid}); its process group '
        'could not be verified on this host — group members may remain. '
        'The job record is kept; the next boot reaps any survivors.',
      );
    }
    return ToolExecutionResult.text('Stopped $id');
  }
  // gh-1438 AC5: the destructive action NEVER acts on a resolved guess —
  // malformed ids keep the shortest error, GC'd ids are honestly done, and
  // every other unknown id gets the closest-ids hint only.
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  if (jobs.prunedLogPath(id) != null) {
    return ToolExecutionResult.text(
      'Job $id already exited (its log was compacted out of the registry) — '
      'nothing to stop.',
    );
  }
  final hint = closestShellJobIds(id, [for (final j in jobs.jobs) j.id]);
  final buffer = StringBuffer(
    'Unknown background job: $id — stop requires the exact job id '
    '(it never acts on a resolved guess).',
  );
  if (hint.isEmpty) {
    buffer.write(' No jobs are retained this session.');
  } else {
    buffer.write(' Closest retained job ids:');
    for (final candidate in hint) {
      final entry = jobs.job(candidate);
      buffer.write(
        '\n- ${entry == null ? candidate : _shellJobStatusLine(entry)}',
      );
    }
  }
  return ToolExecutionResult.text(buffer.toString());
}

